<?php
/**
 * The icons an editor can pick from.
 *
 * Generated by tools/uew/build.mjs into includes/sections/icons.json: every
 * icon the section files already use, then a curated set of line icons
 * (Lucide, ISC licence) and social marks (Simple Icons, CC0). Each entry is the
 * inside of a 24x24 `<svg>` -- the `<svg>` element itself stays the section
 * file's own, so its class, size and colour rules still apply.
 *
 * Two families, because the sections draw them two ways: `line` icons are
 * stroked by the section's CSS, `brand` icons are filled.
 *
 * Deliberately independent of Elementor, so the render path and the checks can
 * use it without loading the editor.
 *
 * @package Umoya_EW
 */

namespace Umoya_EW;

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

final class Icon_Library {

	/**
	 * Every family, as { family: [ { id, label, markup }, ... ] }.
	 *
	 * @return array
	 */
	public static function all() {
		static $library = null;
		if ( null !== $library ) {
			return $library;
		}

		$library = array();
		$file    = UMOYA_EW_PATH . 'includes/sections/icons.json';
		if ( file_exists( $file ) ) {
			$decoded = json_decode( (string) file_get_contents( $file ), true );
			if ( is_array( $decoded ) ) {
				$library = $decoded;
			}
		}

		return $library;
	}

	/**
	 * The markup of every icon in one family.
	 *
	 * @param string $family `line` or `brand`.
	 * @return string[]
	 */
	public static function markups( $family ) {
		$library = self::all();
		$icons   = isset( $library[ $family ] ) ? (array) $library[ $family ] : array();

		return array_values( array_map( function ( $icon ) {
			return (string) $icon['markup'];
		}, $icons ) );
	}
}
